contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint val1, uint val2) public {
        bool reverted1;
        bool reverted2;

        c.SetMinSum(val1); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted1 = true;
        } else {
            reverted1 = false;
        }

        uint after1 = c.MinSum(); if (__ESBMC_reverted()) return;

        c.SetMinSum(val2); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            reverted2 = true;
        } else {
            reverted2 = false;
        }

        uint after2 = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(!reverted1 && !reverted2 && after1 == val1 && after2 == val2);
    }
}

