pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MONEY_BOX c;

    function setUp() public {
        c = new MONEY_BOX();
    }

    function _run(uint256 val1, uint256 val2) internal {
        bool reverted1;
        bool reverted2;
        try c.SetMinSum(val1) {
            reverted1 = false;
        } catch {
            reverted1 = true;
        }
        uint256 after1;
        try c.MinSum() returns (uint256 __r) { after1 = __r; } catch { return; }
        try c.SetMinSum(val2) {
            reverted2 = false;
        } catch {
            reverted2 = true;
        }
        uint256 after2;
        try c.MinSum() returns (uint256 __r) { after2 = __r; } catch { return; }
        assertTrue(!reverted1 && !reverted2 && after1 == val1 && after2 == val2);
    }

    function testFuzz_run(uint256 val1, uint256 val2) public {
        _run(val1, val2);
    }

    receive() external payable {}
}
